              type: "underrun",
              mode: "sab",
              count: this._underrunCount,
              writeHead: writeHead,
              readHead: this._readHead,
              activeSlot: this._activeSlot,
              slotOffset: this._slotOffset,
              bufferSize: this._bufferSize
